import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";

// Prisma formats its embedded schema. Compare lexical tokens, preserving quoted
// values and identifier boundaries; whitespace and comments do not affect generation.
function schemaTokens(schema) {
  return JSON.stringify(
    (schema.match(/"(?:\\.|[^"\\])*"|\/\/[^\n]*|\/\*[\s\S]*?\*\/|[A-Za-z0-9_]+|[^\s]/g) ?? []).filter(
      (token) => !token.startsWith("//") && !token.startsWith("/*"),
    ),
  );
}

/** Reuse only an initialized client generated by the installed CLI for this exact schema. */
export function matchesGeneratedPrismaClient({ sourceSchema, generatedSchema, cliVersion, clientVersion, hasClient }) {
  return (
    hasClient === true &&
    typeof cliVersion === "string" &&
    cliVersion === clientVersion &&
    typeof sourceSchema === "string" &&
    sourceSchema.length > 0 &&
    typeof generatedSchema === "string" &&
    schemaTokens(sourceSchema) === schemaTokens(generatedSchema)
  );
}
export function canReusePrismaClient(cwd) {
  try {
    const require = createRequire(join(cwd, "package.json"));
    const clientRequire = createRequire(require.resolve("@prisma/client"));
    const generatedDir = dirname(clientRequire.resolve(".prisma/client/default"));
    const client = require("@prisma/client");
    return matchesGeneratedPrismaClient({
      sourceSchema: readFileSync(join(cwd, "prisma/schema.prisma"), "utf8"),
      generatedSchema: readFileSync(join(generatedDir, "schema.prisma"), "utf8"),
      cliVersion: require("prisma/package.json").version,
      clientVersion: client.Prisma?.prismaVersion?.client,
      hasClient: typeof client.PrismaClient === "function",
    });
  } catch {
    return false;
  }
}
